"use client";

import type { ChartRoot } from "./chart-utils";
import { useMergedRef } from "../lib/form";
import {
  startTransition,
  useCallback,
  useEffect,
  useEffectEvent,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
  useLayoutEffect,
} from "react";

import { cn } from "../lib/cn";
import { duration, ease } from "../motion/tokens";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { SegmentedControl } from "../segmented/segmented";
import { ChartEmpty } from "./chart-parts";
import { useDockedReadout } from "./chart-fit";
import { clamp, useElementWidth, resolveInstructions, itemAt } from "./chart-utils";
import {
  ChartDockHint,
  defaultCompact,
  scalePosition,
  SequentialLegend,
  sequentialColor,
  useContrastInk,
  useEntrance,
} from "./heatmap";
import { isRtlAt } from "../hooks/use-direction";

import {
  type CohortCell,
  type CohortView,
  defaultCohortChartLabels,
  type CohortChartProps,
  cohortPercent,
  cohortModel,
  DOCK_BAND,
  isolate,
  cssEase,
  DockedReadout,
  useCellsEntrance,
  CellTip,
  type RowView,
  CohortRowView,
} from "./cohort-chart/parts";

export {
  type CohortRow,
  type CohortCell,
  type CohortView,
  type CohortChartLabels,
  defaultCohortChartLabels,
  type CohortChartProps,
  cohortPercent,
  cohortModel,
} from "./cohort-chart/parts";
export { type CohortTableProps, CohortTable } from "./cohort-chart/table";
/* ======================================================================
 * CohortChart
 * ====================================================================== */

/**
 * Retention cohort table: one row per cohort, one column per period since it started, each cell
 * coloured on a single-hue scale by the share of the cohort still active.
 *
 * - A weighted-average row sits on top; the tooltip compares each cell with it.
 * - Switch between percentages and user counts (the colour always follows retention, so cohorts
 *   of different sizes stay comparable).
 * - It is a real ARIA grid: Tab lands on one cell, the arrow keys move (Home / End along a row,
 *   Ctrl+Home / Ctrl+End to the corners), Enter or Space calls onCellClick. Screen readers hear
 *   the cohort and the period with every cell.
 * - Wide or long tables scroll inside their own container; the header row and the cohort column
 *   stay put.
 * - Cells bloom in on a diagonal wave the first time the table scrolls into view; switching
 *   views sweeps the new numbers in with one glint across the grid. Instant with reduced motion.
 *
 * @example
 * ```tsx
 * import { CohortChart } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <CohortChart
 *       data={[{ cohort: "Jan 2026", size: 120, values: [120, 84, 61] }]}
 *       aria-label="Retention by signup month"
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts/cohort-retention
 */
export function CohortChart({
  data,
  valuesAre = "counts",
  periods,
  view: viewProp,
  defaultView = "percent",
  onViewChange,
  viewToggle = true,
  average = true,
  color = 1,
  domain,
  steps = 0,
  maxHeight,
  format: formatProp,
  formatPercent: formatPercentProp,
  locale,
  legend = true,
  onCellClick,
  emptyState,
  labels: labelOverrides,
  "aria-label": ariaLabel,
  className,
  ref: outerRef,
  ...rest
}: ChartRoot<CohortChartProps>) {
  const labels = { ...defaultCohortChartLabels, ...labelOverrides };
  const format = formatProp ?? defaultCompact(locale);
  const pct = formatPercentProp ?? cohortPercent(locale);
  const reduced = useSheenReducedMotion();
  const uid = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const tableRef = useRef<HTMLTableElement>(null);
  const sweepRef = useRef<HTMLDivElement>(null);
  const firstColRef = useRef<HTMLTableCellElement>(null);
  const headRef = useRef<HTMLTableSectionElement>(null);
  const play = useEntrance(rootRef, reduced);

  // The root is always mounted (also while empty, e.g. loading), so its width is known from the
  // first render with data, and the entrance observer is attached from the start.
  const [measureRef, rootW] = useElementWidth<HTMLDivElement>();
  const setRoot = useMergedRef(rootRef, measureRef);
  const rootMerged = useMergedRef(setRoot, outerRef);
  const docked = useDockedReadout(rootW);

  const [innerView, setInnerView] = useState<CohortView>(defaultView);
  const view = viewProp ?? innerView;
  const setView = (v: CohortView) => {
    // Every cell's text changes: render the grid as a transition (in slices that never block
    // input), whether the view is ours or the parent's.
    startTransition(() => {
      if (viewProp === undefined) setInnerView(v);
      onViewChange?.(v);
    });
  };

  const model = useMemo(() => cohortModel(data, valuesAre, periods, average), [data, valuesAre, periods, average]);
  const { rows, periods: periodCount } = model;

  // The ramp spans the retention actually seen after period 0 (period 0 is 100% by definition and
  // would squash every other cell into one shade); the legend prints both ends.
  const [lo, hi] = useMemo<[number, number]>(() => {
    if (domain) return domain;
    let min = Infinity;
    let max = -Infinity;
    for (const r of rows)
      for (let p = 1; p < r.cells.length; p++) {
        const v = r.cells[p]?.ratio;
        if (v === null || v === undefined) continue;
        min = Math.min(min, v);
        max = Math.max(max, v);
      }
    if (!(max > 0)) return [0, 1];
    const floor = Math.floor((min * 100) / 5) * 0.05; // a round lower end: 12% → 10%
    return [Math.max(0, floor < max ? floor : 0), max];
  }, [rows, domain]);

  const fillOf = useCallback(
    (ratio: number | null) =>
      ratio === null ? null : sequentialColor(scalePosition(clamp(ratio, lo, hi), lo, hi, steps), color),
    [lo, hi, steps, color],
  );
  const fills = useMemo(
    () => rows.flatMap((r) => r.cells.map((c) => fillOf(c.ratio)).filter((f): f is string => f !== null)),
    [rows, fillOf],
  );
  const ink = useContrastInk(rootRef, fills);

  /* ---------- Active cell (pointer or keyboard) ---------- */

  const [active, setActive] = useState<{ r: number; c: number; from: "pointer" | "keyboard" } | null>(null);
  const [focusCell, setFocusCell] = useState<{ r: number; c: number }>({ r: 0, c: 0 });
  const act = active && active.r < rows.length && active.c < periodCount ? active : null;

  // Scroll state drives the sticky header / column surfaces (only shown while something passes
  // under them). It flips at most twice per scroll gesture; the tooltip follows its cell by itself.
  const [scrolled, setScrolled] = useState({ x: false, y: false });
  // While the grid scrolls, the cells sliding under a still pointer must not count as hovers
  // (data-scrolling, until the scroll settles), so scrolling never re-renders a row.
  const scrollIdle = useRef(0);
  useEffect(() => () => window.clearTimeout(scrollIdle.current), []);
  const onScroll = () => {
    const el = scrollRef.current;
    if (!el) return;
    const next = { x: Math.abs(el.scrollLeft) > 1, y: el.scrollTop > 1 };
    setScrolled((s) => (s.x === next.x && s.y === next.y ? s : next));
    if (!el.hasAttribute("data-scrolling")) el.setAttribute("data-scrolling", "");
    window.clearTimeout(scrollIdle.current);
    scrollIdle.current = window.setTimeout(() => el.removeAttribute("data-scrolling"), 150);
  };

  // Keep focus scrolling clear of the sticky column and header. A ResizeObserver reports their
  // size after layout (and again whenever it changes); the old layout effect read offsetWidth and
  // offsetHeight after EVERY render, forcing a layout of the whole table each time.
  const hasRows = rows.length > 0;
  useEffect(() => {
    const el = scrollRef.current;
    const col = firstColRef.current;
    const head = headRef.current;
    if (!el || !hasRows || typeof ResizeObserver === "undefined") return;
    const apply = () => {
      el.style.scrollPaddingInlineStart = `${(col?.offsetWidth ?? 0) + 4}px`;
      el.style.scrollPaddingTop = `${(head?.offsetHeight ?? 0) + 4}px`;
    };
    const observer = new ResizeObserver(apply);
    if (col) observer.observe(col);
    if (head) observer.observe(head);
    return () => observer.disconnect();
  }, [hasRows]);

  useCellsEntrance(tableRef, play && rows.length > 0, reduced);

  // Switching views: the new numbers are swept in by ONE glint that crosses the grid (a single
  // compositor animation, however many cells there are), from the inline start to the end.
  const sweep = useEffectEvent(() => {
    const band = sweepRef.current;
    const table = tableRef.current;
    const scroller = scrollRef.current;
    if (reduced || !band || !table || !scroller || typeof band.animate !== "function") return;
    const viewW = scroller.clientWidth;
    const bandW = Math.max(120, Math.round(viewW * 0.4));
    band.style.width = `${bandW}px`;
    band.style.height = `${table.offsetHeight}px`;
    const rtl = isRtlAt(scroller);
    const s = Math.abs(scroller.scrollLeft);
    const col = firstColRef.current?.offsetWidth ?? 0;
    // Physical x of the band: from behind the cohort column to past the view's far edge.
    const [from, to] = rtl ? [-s - col + bandW, -s - viewW] : [s + col - bandW, s + viewW];
    band.animate(
      [
        { transform: `translateX(${from}px)`, opacity: 0 },
        { opacity: 1, offset: 0.25 },
        { opacity: 1, offset: 0.75 },
        { transform: `translateX(${to}px)`, opacity: 0 },
      ],
      { duration: duration.slower * 1000, easing: cssEase(ease.inOut) },
    );
  });
  const shownView = useRef(view);
  useEffect(() => {
    if (shownView.current === view) return;
    shownView.current = view;
    sweep();
  }, [view]);

  /* ---------- Cells, precomputed: a hover re-renders only the two rows it touches ---------- */

  const averageLabel = labelOverrides?.average ?? defaultCohortChartLabels.average;
  const averageNote = labelOverrides?.averageNote ?? defaultCohortChartLabels.averageNote;
  const sizeLabel = labelOverrides?.size ?? defaultCohortChartLabels.size;
  const retainedLabel = labelOverrides?.retained ?? defaultCohortChartLabels.retained;
  const notYet = labelOverrides?.notYet ?? defaultCohortChartLabels.notYet;
  const rowViews = useMemo<RowView[]>(
    () =>
      rows.map((row, r) => ({
        key: row.average ? "\u0000avg" : `${row.name}\u0000${r}`,
        name: row.average ? averageLabel : row.name,
        sub: row.average ? averageNote : sizeLabel(format(row.size)),
        average: row.average,
        cells: row.cells.map((cell, c) => {
          const fill = fillOf(cell.ratio);
          const text = cell.ratio === null ? "" : view === "percent" ? pct(cell.ratio) : format(cell.count ?? 0);
          const other =
            view === "percent"
              ? retainedLabel(format(cell.count ?? 0), format(row.size))
              : cell.ratio === null
                ? ""
                : pct(cell.ratio);
          return {
            fill,
            light: fill !== null && ink(fill) === "light",
            text,
            sr: cell.ratio === null ? notYet : `${text}, ${other}`,
            delay: fill ? Math.min(0.7, (r + c) * 0.028).toFixed(3) : undefined,
            reached: cell.ratio !== null,
          };
        }),
      })),
    // Only the strings it uses: `labels` itself is a new object every render.
    [rows, view, fillOf, ink, format, pct, averageLabel, averageNote, sizeLabel, retainedLabel, notYet],
  );

  const activateCell = useCallback((r: number, c: number, from: "pointer" | "keyboard") => {
    if (from === "pointer" && scrollRef.current?.hasAttribute("data-scrolling")) return;
    setActive((a) => (a?.r === r && a.c === c && a.from === from ? a : { r, c, from }));
  }, []);
  const focusCellAt = useCallback(
    (r: number, c: number) => {
      setFocusCell((f) => (f.r === r && f.c === c ? f : { r, c }));
      activateCell(r, c, "keyboard");
    },
    [activateCell],
  );
  // The click handler reads the latest props from a ref (set after each commit), so it stays the
  // same function and never breaks the rows' memo.
  const latest = useRef({ onCellClick, rows });
  useLayoutEffect(() => {
    latest.current = { onCellClick, rows };
  });
  const clickCell = useCallback((r: number, c: number) => {
    const { onCellClick: click, rows: all } = latest.current;
    const row = all[r];
    const cell = row?.cells[c];
    click?.({
      cohort: row && !row.average ? row.name : null,
      period: c,
      ratio: cell?.ratio ?? null,
      count: cell?.count ?? null,
      size: row?.size ?? 0,
    });
  }, []);

  const hasData = rows.length > 0 && periodCount > 0;
  if (!hasData) {
    return (
      <div {...rest} ref={rootMerged} className={cn("w-full min-w-0", className)}>
        <ChartEmpty height={220} aria-label={ariaLabel}>
          {emptyState}
        </ChartEmpty>
      </div>
    );
  }

  const cellAt = (r: number, c: number): CohortCell => {
    const row = rows[r];
    const cell = row?.cells[c];
    return {
      cohort: row && !row.average ? row.name : null,
      period: c,
      ratio: cell?.ratio ?? null,
      count: cell?.count ?? null,
      size: row?.size ?? 0,
    };
  };

  const focusAt = (r: number, c: number) => {
    const rr = clamp(r, 0, rows.length - 1);
    const cc = clamp(c, 0, periodCount - 1);
    setFocusCell({ r: rr, c: cc });
    setActive({ r: rr, c: cc, from: "keyboard" });
    tableRef.current?.querySelector<HTMLElement>(`[data-r="${rr}"][data-c="${cc}"]`)?.focus();
  };

  function onKeyDown(event: KeyboardEvent<HTMLTableElement>) {
    const target = (event.target as HTMLElement).closest<HTMLElement>("[data-r]");
    if (!target) return;
    const r = Number(target.dataset.r);
    const c = Number(target.dataset.c);
    const ctrl = event.ctrlKey || event.metaKey;
    const rtl = isRtlAt(target);
    const right = rtl ? -1 : 1;
    switch (event.key) {
      case "ArrowRight":
        focusAt(r, c + right);
        break;
      case "ArrowLeft":
        focusAt(r, c - right);
        break;
      case "ArrowDown":
        focusAt(r + 1, c);
        break;
      case "ArrowUp":
        focusAt(r - 1, c);
        break;
      case "Home":
        focusAt(ctrl ? 0 : r, 0);
        break;
      case "End":
        focusAt(ctrl ? rows.length - 1 : r, ctrl ? periodCount - 1 : Math.max(0, lastReached(r)));
        break;
      case "PageDown":
        focusAt(rows.length - 1, c);
        break;
      case "PageUp":
        focusAt(0, c);
        break;
      case "Enter":
      case " ":
        if (!onCellClick) return;
        onCellClick(cellAt(r, c));
        break;
      case "Escape":
        if (!act) return;
        setActive(null);
        break;
      default:
        return;
    }
    event.preventDefault();
  }

  /** Last period this row has a value for. */
  const lastReached = (r: number) => {
    const cells = rows[r]?.cells ?? [];
    for (let p = cells.length - 1; p >= 0; p--) if (cells[p]?.ratio !== null) return p;
    return 0;
  };

  /* ---------- Tooltip ---------- */

  const avgRow = rows[0]?.average ? rows[0] : null;
  const points = new Intl.NumberFormat(locale ?? "en", { maximumFractionDigits: 1 });
  let tooltip: ReactNode = null;
  if (act) {
    const row = itemAt(rows, act.r);
    const cell = itemAt(row.cells, act.c);
    const name = row.average ? labels.average : row.name;
    const retained = cell.ratio === null ? "" : labels.retained(format(cell.count ?? 0), format(row.size));
    // How the cell compares with the weighted average of its period.
    let comparison: { text: string; arrow: string } | null = null;
    const avgRatio = avgRow?.cells[act.c]?.ratio ?? null;
    if (!row.average && cell.ratio !== null && avgRatio !== null) {
      const rounded = Math.round((cell.ratio - avgRatio) * 1000) / 10;
      const direction = rounded > 0 ? "above" : rounded < 0 ? "below" : "same";
      comparison = {
        text: labels.vsAverage(points.format(Math.abs(rounded)), direction),
        arrow: direction === "above" ? "▲" : direction === "below" ? "▼" : "=",
      };
    }
    if (docked) {
      tooltip = (
        <DockedReadout
          title={`${isolate(name)} · ${isolate(labels.period(act.c))}`}
          value={cell.ratio === null ? "" : pct(cell.ratio)}
          color={fillOf(cell.ratio)}
          details={
            cell.ratio === null
              ? [labels.notYet]
              : [retained, comparison ? `${comparison.arrow} ${comparison.text}` : ""].filter(Boolean)
          }
        />
      );
    } else if (rootW > 0) {
      const tipRows =
        cell.ratio === null
          ? [{ label: "", value: isolate(labels.notYet), color: "transparent", kind: "rect" as const }]
          : [
              {
                label: isolate(labels.retention),
                value: isolate(pct(cell.ratio)),
                color: fillOf(cell.ratio) ?? "transparent",
                kind: "rect" as const,
              },
              { label: isolate(retained), value: "", color: "transparent", kind: "rect" as const },
            ];
      if (comparison)
        tipRows.push({ label: isolate(comparison.text), value: comparison.arrow, color: "transparent", kind: "rect" });
      tooltip = (
        <CellTip
          rootRef={rootRef}
          scrollRef={scrollRef}
          tableRef={tableRef}
          r={act.r}
          c={act.c}
          layoutKey={`${view}:${rootW}:${periodCount}:${rows.length}`}
          title={`${isolate(name)} · ${isolate(labels.period(act.c))}`}
          rows={tipRows}
        />
      );
    }
  }

  const activeRatio = act ? (rows[act.r]?.cells[act.c]?.ratio ?? null) : null;
  // A near-opaque surface (no backdrop blur: a sticky cell per row would blow the glass budget and
  // make scrolling repaint) for the sticky header / column, only while something scrolls under them.
  const stickyBg = "bg-[color-mix(in_oklab,var(--sheen-chart-surface)_96%,transparent)]";
  // On a phone the sticky cohort column may take about a third of the width: its names wrap
  // instead, so more periods stay in view.
  const nameMax = rootW > 0 && rootW < 480 ? Math.max(84, Math.round(rootW * 0.32)) : undefined;

  return (
    <div
      {...rest}
      ref={rootMerged}
      className={cn("relative flex w-full min-w-0 flex-col gap-3", className)}
      style={{ paddingTop: docked ? DOCK_BAND : 0 }}
    >
      {viewToggle && (
        <div className="flex justify-end">
          <SegmentedControl
            size="sm"
            aria-label={labels.viewLabel}
            value={view}
            onValueChange={(v) => setView(v as CohortView)}
            items={[
              { value: "percent", label: labels.percent },
              { value: "count", label: labels.count },
            ]}
          />
        </div>
      )}

      <div
        ref={scrollRef}
        onScroll={onScroll}
        className="relative overflow-auto overscroll-contain rounded-sheen-sm [scrollbar-width:thin]"
        style={{ maxHeight }}
      >
        <table
          ref={tableRef}
          // eslint-disable-next-line jsx-a11y/no-noninteractive-element-to-interactive-role -- an ARIA grid: cell-to-cell keyboard navigation is handled in onKeyDown on the table (the instructions are read with its name)
          role="grid"
          aria-label={ariaLabel}
          aria-describedby={`${uid}-help`}
          aria-readonly="true"
          onKeyDown={onKeyDown}
          onPointerLeave={(e) => e.pointerType === "mouse" && act?.from === "pointer" && setActive(null)}
          onBlur={(e) => {
            if (!e.currentTarget.contains(e.relatedTarget)) setActive((a) => (a?.from === "keyboard" ? null : a));
          }}
          // While the entrance wave runs, cells wait (invisible) for their diagonal's turn.
          className="w-full border-separate border-spacing-0 text-xs data-entering:[&_[data-delay]]:opacity-0"
        >
          <thead ref={headRef}>
            <tr>
              <th
                ref={firstColRef}
                scope="col"
                className={cn(
                  "sticky start-0 top-0 z-3 px-2 pb-1.5 text-start align-bottom font-medium whitespace-nowrap text-sheen-fg-muted",
                  (scrolled.x || scrolled.y) && stickyBg,
                )}
              >
                {labels.cohort}
              </th>
              {Array.from({ length: periodCount }, (_, p) => (
                <th
                  key={p}
                  scope="col"
                  className={cn(
                    "sticky top-0 z-2 px-0.5 pb-1.5 text-center align-bottom font-medium whitespace-nowrap",
                    "transition-colors duration-(--sheen-duration-fast)",
                    act?.c === p ? "text-sheen-fg" : "text-sheen-fg-muted",
                    scrolled.y && stickyBg,
                  )}
                >
                  {labels.period(p)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rowViews.map((row, r) => (
              <CohortRowView
                key={row.key}
                row={row}
                r={r}
                activeC={act?.r === r ? act.c : -1}
                focusC={focusCell.r === r ? focusCell.c : -1}
                stickyBg={scrolled.x ? stickyBg : undefined}
                nameMax={nameMax}
                clickable={!!onCellClick}
                onActivate={activateCell}
                onFocusCell={focusCellAt}
                onClickCell={clickCell}
              />
            ))}
          </tbody>
        </table>
        {/* The glint that sweeps the new numbers in on a view switch: above the cells, under the
            sticky header and cohort column (z-1 and up), invisible at rest. */}
        <div
          ref={sweepRef}
          aria-hidden
          className={cn(
            "pointer-events-none absolute start-0 top-0 z-0 opacity-0 forced-colors:hidden",
            "bg-linear-to-r from-transparent via-[light-dark(color-mix(in_oklch,var(--sheen-ink-on-dark)_55%,transparent),color-mix(in_oklch,var(--sheen-ink-on-dark)_16%,transparent))] to-transparent",
          )}
        />
      </div>
      <p id={`${uid}-help`} className="sr-only">
        {resolveInstructions(labels.instructions)}
      </p>

      {/* Scales read low → high left to right on every page (as the ramp is drawn). */}
      {legend && (
        // The caption wraps onto its own line on narrow charts; the key itself stays on one line.
        <div dir="ltr" aria-hidden className="flex flex-wrap items-center justify-end gap-x-3 gap-y-1">
          <span className="text-2xs font-medium text-sheen-fg-muted">{labels.retention}</span>
          <SequentialLegend
            className="flex-nowrap"
            min={lo}
            max={hi}
            color={color}
            steps={steps}
            format={pct}
            marker={activeRatio === null ? null : scalePosition(clamp(activeRatio, lo, hi), lo, hi, steps)}
          />
        </div>
      )}
      {tooltip ?? (docked && <ChartDockHint>{labels.hint}</ChartDockHint>)}
    </div>
  );
}

"use client";

import { memo, useEffect, useRef, useState, type ReactNode, type RefObject, useLayoutEffect } from "react";

import { cn } from "../../lib/cn";
import { duration, ease } from "../../motion/tokens";
import { LegendKey } from "../chart-parts";
import { TOOLTIP_DOCK_SPACE, type ChartColor, type ChartInstructions, itemAt } from "../chart-utils";
import { ChartTip, type ChartTipAnchor } from "../heatmap";

/* ======================================================================
 * Types
 * ====================================================================== */

/**
 * One cohort of a CohortChart: its name, how many users it started with and the share or count still
 * active in each period.
 */
export type CohortRow = {
  /** Name of the cohort, e.g. "Jan 2026" or "Week of 3 Mar". */
  cohort: string;
  /** How many users started in this cohort. */
  size: number;
  /**
   * Users still active in each period, period 0 first (counts, or ratios with valuesAre="ratios").
   * null for periods the cohort hasn't reached yet: they stay blank, never 0%.
   */
  values: readonly (number | null)[];
};

/** A cell, as passed to `onCellClick`. `cohort` is null for the average row. */
export type CohortCell = {
  cohort: string | null;
  period: number;
  ratio: number | null;
  count: number | null;
  size: number;
};

/** How a CohortChart shows its cells: as `percent` of the cohort or as `count` of users. */
export type CohortView = "percent" | "count";

/**
 * Every string CohortChart speaks or shows, so it can be translated: pass a `Partial` as the `labels`
 * prop. Entries that need a value are functions.
 */
export type CohortChartLabels = {
  /** Column header for period `i`, e.g. "Week 3". */
  period: (i: number) => string;
  /** Header of the cohort column. */
  cohort: string;
  /** Second line under each cohort's name: its size. */
  size: (formattedSize: string) => string;
  /** Name of the weighted-average row, and its second line. */
  average: string;
  averageNote: string;
  /** Options of the view switch, and its accessible name. */
  percent: string;
  count: string;
  viewLabel: string;
  /** Legend caption. */
  retention: string;
  /** Read for a period a cohort hasn't reached yet. */
  notYet: string;
  /** "529 of 1,284 users". */
  retained: (count: string, size: string) => string;
  /** "3.2 pts above average" (`delta` is the formatted size of the gap, without a sign). */
  vsAverage: (delta: string, direction: "above" | "below" | "same") => string;
  /** Appended to the grid's accessible name. */
  instructions: ChartInstructions;
  /** Shown in the readout band of a narrow touch chart while nothing is being read. */
  hint: string;
};

/**
 * The built-in English strings of CohortChart; spread it into your own `labels` and change what you
 * need. This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultCohortChartLabels: CohortChartLabels = {
  period: (i) => `Week ${i}`,
  cohort: "Cohort",
  size: (n) => `${n} users`,
  average: "Average",
  averageNote: "All cohorts, weighted",
  percent: "%",
  count: "Users",
  viewLabel: "Show retention as",
  retention: "Retention",
  notYet: "Not yet reached",
  retained: (count, size) => `${count} of ${size} users`,
  vsAverage: (delta, direction) => (direction === "same" ? "Same as average" : `${delta} pts ${direction} average`),
  instructions:
    "Use the arrow keys to move between cells; Home and End jump along a row, Ctrl+Home and Ctrl+End to the corners.",
  hint: "Tap a cell for details",
};

/**
 * Props of CohortChart. The component's own doc comment describes its behaviour, keyboard use and
 * accessibility.
 */
export type CohortChartProps = {
  /** Takes one row per cohort, oldest first. */
  data: readonly CohortRow[];
  /** How `values` are given: user counts (default) or retention ratios 0–1. */
  valuesAre?: "counts" | "ratios";
  /** Sets the number of period columns. Default: the longest row. */
  periods?: number;
  /** Show retention as percentages or user counts (controlled). */
  view?: CohortView;
  /** Sets the starting view when uncontrolled. Default "percent". */
  defaultView?: CohortView;
  /** Called when the person switches between the percent and count views. */
  onViewChange?: (view: CohortView) => void;
  /** Show the % / users switch. Default true. */
  viewToggle?: boolean;
  /** Add a weighted-average row on top. Default true. */
  average?: boolean;
  /** Hue of the sequential scale: a palette slot 1–8. Default 1. */
  color?: ChartColor;
  /** Retention range of the colour scale (0–1). Default: the lowest to the highest retention after period 0. */
  domain?: [number, number];
  /** Classes on the colour scale (e.g. 5); 0 = continuous. */
  steps?: number;
  /** Tallest the table gets before it scrolls inside (its header row stays put). */
  maxHeight?: number;
  /** Formats a cohort count for the cell labels, tooltips and data table: takes the number, returns the text shown. Default: compact numbers in `locale`. */
  format?: (n: number) => string;
  /**
   * Formats ratios: percentages with one decimal in `locale` ("41.2%"; period 0 reads "100%").
   *
   * @default percentages, one decimal
   */
  formatPercent?: (ratio: number) => string;
  /** Locale of the default formats. Default "en". */
  locale?: string;
  /** Show the colour key. Default true. */
  legend?: boolean;
  /** Called with a cell on click, Enter or Space. */
  onCellClick?: (cell: CohortCell) => void;
  /** Shown when there is nothing to show. */
  emptyState?: ReactNode;
  /** Overrides for the chart's built-in English strings. */
  labels?: Partial<CohortChartLabels>;
  /** Accessible name of the chart; describe what it shows. */
  "aria-label": string;
  className?: string;
};

/* ======================================================================
 * Model
 * ====================================================================== */

/** One cohort cell: retention ratio and count, or null when absent. @internal */
export type Cell = { ratio: number | null; count: number | null };
/** The cohort rows, each with its cells, and the period count. @internal */
export type Model = { rows: { name: string; size: number; cells: Cell[]; average: boolean }[]; periods: number };

/** Returns a value only when it is a finite number, otherwise null. @internal */
export function finite(v: unknown): number | null {
  return typeof v === "number" && Number.isFinite(v) ? v : null;
}

/** A cache of percent formatters by locale. @internal */
export const cohortPercents = new Map<string, (ratio: number) => string>();

/**
 * Retention as a percentage with one fixed decimal ("18.0%", never "18%" beside "18.5%"), so a
 * column of them lines up; exactly 100% (period 0) stays "100%".
 *
 * @see /charts/cohort-retention
 */
export function cohortPercent(locale = "en") {
  let fn = cohortPercents.get(locale);
  if (!fn) {
    const make = (digits: number) => {
      const o: Intl.NumberFormatOptions = {
        style: "percent",
        minimumFractionDigits: digits,
        maximumFractionDigits: digits,
      };
      try {
        return new Intl.NumberFormat(locale, o);
      } catch {
        return new Intl.NumberFormat("en", o);
      }
    };
    const one = make(1);
    const whole = make(0);
    fn = (ratio) => (Math.abs(ratio - 1) < 5e-5 ? whole.format(1) : one.format(ratio));
    cohortPercents.set(locale, fn);
  }
  return fn;
}

/** Ratios and counts for every cohort, plus the weighted average of each period.
 *
 * @see /charts/cohort-retention
 */
export function cohortModel(
  data: readonly CohortRow[],
  valuesAre: "counts" | "ratios" = "counts",
  periods?: number,
  withAverage = true,
): Model {
  const n = Math.max(0, periods ?? data.reduce((m, row) => Math.max(m, row.values.length), 0));
  const rows = data.map((row) => {
    const size = Math.max(0, finite(row.size) ?? 0);
    const cells: Cell[] = Array.from({ length: n }, (_, p) => {
      const v = finite(row.values[p]);
      if (v === null) return { ratio: null, count: null };
      if (valuesAre === "ratios") return { ratio: v, count: Math.round(v * size) };
      return { ratio: size > 0 ? v / size : null, count: v };
    });
    return { name: row.cohort, size, cells, average: false };
  });
  if (!withAverage || rows.length < 2) return { rows, periods: n };
  // Weighted average: retained users over starting users, among the cohorts that reached the period.
  const avg: Cell[] = Array.from({ length: n }, (_, p) => {
    let kept = 0;
    let base = 0;
    for (const r of rows) {
      const c = r.cells[p];
      if (c?.count == null || r.size <= 0) continue;
      kept += c.count;
      base += r.size;
    }
    return base > 0 ? { ratio: kept / base, count: kept } : { ratio: null, count: null };
  });
  const total = rows.reduce((s, r) => s + r.size, 0);
  return { rows: [{ name: "", size: total, cells: avg, average: true }, ...rows], periods: n };
}

/** Height of the band a narrow touch chart reserves above the grid for the docked readout (two lines). */
export const DOCK_BAND = TOOLTIP_DOCK_SPACE + 18;

/** Wraps text in a first-strong isolate, so numbers and dates never reorder inside right-to-left text. */
export const isolate = (text: string) => (text ? `⁨${text}⁩` : text);
/** An easing curve as a CSS `cubic-bezier` string. @internal */
export const cssEase = (e: readonly number[]) => `cubic-bezier(${e.join(",")})`;

/**
 * The reading on a narrow touch chart, pinned in the band above the grid: two fixed lines (the
 * cell and its retention, then the users and the comparison with the average), each truncated, so
 * it never spills over the cells. Every part is bidi-isolated, so figures keep their order on
 * right-to-left pages. Visual only: screen readers read the focused cell itself.
 */
export function DockedReadout({
  title,
  value,
  color,
  details,
}: {
  title: string;
  value: string;
  color: string | null;
  details: string[];
}) {
  return (
    <div
      aria-hidden
      data-slot="chart-readout"
      className="glass-3 pointer-events-none absolute inset-x-0 top-0 z-10 flex h-12 flex-col justify-center gap-0.5 rounded-sheen-md px-3 text-xs"
    >
      <p className="flex min-w-0 items-center gap-2">
        {color && <LegendKey color={color} />}
        <span dir="auto" className="min-w-0 truncate font-medium text-sheen-fg">
          {title}
        </span>
        <bdi className="ms-auto shrink-0 font-semibold text-sheen-fg tabular-nums">{value}</bdi>
      </p>
      <p dir="auto" className="truncate text-sheen-fg-muted">
        {details.map((part, i) => (
          <span key={i}>
            {i > 0 && " · "}
            <bdi>{part}</bdi>
          </span>
        ))}
      </p>
    </div>
  );
}

/**
 * First-view entrance of the cells: a diagonal wave (WAAPI on each fill, transform + opacity only).
 * The animations are created diagonal by diagonal, just before each one's turn, instead of all in
 * the first frame, so even a big grid never spends one long task setting the wave up. Until its
 * turn, a cell is held invisible by `data-entering` on the root.
 */
export function useCellsEntrance(ref: RefObject<HTMLElement | null>, play: boolean, reduced: boolean) {
  const done = useRef(false);
  const running = useRef<Animation[]>([]);
  const stop = useRef<() => void>(() => undefined);
  useLayoutEffect(() => {
    if (!play || done.current) return;
    const root = ref.current;
    if (!root) return;
    done.current = true;
    if (reduced || typeof root.animate !== "function") return;
    // Cells grouped by their delay (one group per diagonal), earliest first.
    const groups = new Map<number, HTMLElement[]>();
    for (const el of root.querySelectorAll<HTMLElement>("[data-delay]")) {
      const d = Number(el.dataset.delay ?? 0);
      const group = groups.get(d);
      if (group) group.push(el);
      else groups.set(d, [el]);
    }
    const queue = [...groups.entries()].sort((a, b) => a[0] - b[0]);
    if (!queue.length) return;
    root.toggleAttribute("data-entering", true);
    const easing = cssEase(ease.out);
    const t0 = performance.now();
    let next = 0;
    let raf = 0;
    const finish = () => {
      // Hand the cells back to their own (visible) style, then drop the held animations.
      root.toggleAttribute("data-entering", false);
      for (const a of running.current) a.cancel();
      running.current = [];
    };
    const tick = () => {
      const elapsed = (performance.now() - t0) / 1000;
      // Start every diagonal due within the next two frames.
      while (next < queue.length && itemAt(queue, next)[0] <= elapsed + 0.034) {
        const [delay, els] = itemAt(queue, next++);
        for (const el of els)
          running.current.push(
            el.animate(
              [
                { opacity: 0, transform: "scale(0.82)" },
                { opacity: 1, transform: "none" },
              ],
              {
                duration: duration.slow * 1000,
                delay: Math.max(0, delay - elapsed) * 1000,
                easing,
                fill: "both",
              },
            ),
          );
      }
      if (next < queue.length) raf = requestAnimationFrame(tick);
      else running.current.at(-1)?.finished.then(finish, () => undefined);
    };
    tick();
    stop.current = () => {
      cancelAnimationFrame(raf);
      finish();
    };
  }, [play, reduced, ref]);
  // Reduced motion switched on mid-way, or unmounting: everything shows at once.
  useEffect(() => {
    if (reduced) stop.current();
  }, [reduced]);
  useEffect(() => () => stop.current(), []);
}

/**
 * The glass tooltip beside a cell. It measures the cell after layout, and again (once per frame)
 * while the grid scrolls, so the chart never reads layout during render and never re-renders on
 * scroll: only this small component does.
 */
export function CellTip({
  rootRef,
  scrollRef,
  tableRef,
  r,
  c,
  layoutKey,
  title,
  rows,
}: {
  rootRef: RefObject<HTMLElement | null>;
  scrollRef: RefObject<HTMLElement | null>;
  tableRef: RefObject<HTMLElement | null>;
  r: number;
  c: number;
  /** Anything that moves the cells (the view, the width): measure again when it changes. */
  layoutKey: string;
  title: string;
  rows: { label: string; value: string; color: string; kind: "rect" }[];
}) {
  const [box, setBox] = useState<{ anchor: ChartTipAnchor; w: number; h: number } | null>(null);
  useLayoutEffect(() => {
    const root = rootRef.current;
    const scroller = scrollRef.current;
    if (!root) return;
    let raf = 0;
    const measure = () => {
      raf = 0;
      const cell = tableRef.current?.querySelector<HTMLElement>(`[data-r="${r}"][data-c="${c}"]`);
      const rb = root.getBoundingClientRect();
      const b = cell?.getBoundingClientRect();
      setBox(
        b
          ? { anchor: { x: b.left - rb.left, y: b.top - rb.top, w: b.width, h: b.height }, w: rb.width, h: rb.height }
          : null,
      );
    };
    measure();
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(measure);
    };
    scroller?.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      scroller?.removeEventListener("scroll", onScroll);
      cancelAnimationFrame(raf);
    };
  }, [r, c, layoutKey, rootRef, scrollRef, tableRef]);
  if (!box) return null;
  return (
    <ChartTip
      title={title}
      rows={rows}
      anchor={box.anchor}
      bounds={{ w: box.w, h: box.h }}
      order={["below", "above", "right", "left"]}
    />
  );
}

/** The drawn state of one cell: fill, text and readability. @internal */
export type CellView = {
  fill: string | null;
  light: boolean;
  text: string;
  sr: string;
  delay: string | undefined;
  reached: boolean;
};
/** The drawn state of one cohort row. @internal */
export type RowView = { key: string; name: string; sub: string; average: boolean; cells: CellView[] };

/** One cohort's row. Memoised: reading a cell re-renders only its row (and the row it left). */
export const CohortRowView = memo(function CohortRowView({
  row,
  r,
  activeC,
  focusC,
  stickyBg,
  nameMax,
  clickable,
  onActivate,
  onFocusCell,
  onClickCell,
}: {
  row: RowView;
  r: number;
  /** The column being read in this row (-1: none). */
  activeC: number;
  /** The column holding the grid's tab stop in this row (-1: none). */
  focusC: number;
  stickyBg: string | undefined;
  nameMax: number | undefined;
  clickable: boolean;
  onActivate: (r: number, c: number, from: "pointer" | "keyboard") => void;
  onFocusCell: (r: number, c: number) => void;
  onClickCell: (r: number, c: number) => void;
}) {
  return (
    <tr className={cn(row.average && "[&>*]:pb-1.5")}>
      <th
        scope="row"
        className={cn(
          "sticky start-0 z-1 py-px ps-2 pe-3 text-start align-middle font-normal whitespace-nowrap",
          stickyBg,
        )}
      >
        <span
          dir="auto"
          style={nameMax === undefined ? undefined : { width: nameMax }}
          className={cn(
            "block leading-tight transition-colors duration-(--sheen-duration-fast)",
            nameMax !== undefined && "whitespace-normal [overflow-wrap:anywhere]",
            activeC >= 0 ? "font-semibold text-sheen-fg" : row.average ? "font-medium text-sheen-fg" : "text-sheen-fg",
          )}
        >
          {row.name}
        </span>
        <span
          dir="auto"
          style={nameMax === undefined ? undefined : { width: nameMax }}
          className={cn(
            "block text-2xs leading-tight text-sheen-fg-muted tabular-nums",
            nameMax !== undefined && "whitespace-normal",
          )}
        >
          {row.sub}
        </span>
      </th>
      {row.cells.map((cell, c) => (
        <td
          key={c}
          role="gridcell"
          data-r={r}
          data-c={c}
          tabIndex={focusC === c ? 0 : -1}
          onFocus={() => onFocusCell(r, c)}
          onPointerEnter={(e) => e.pointerType === "mouse" && onActivate(r, c, "pointer")}
          onPointerDown={(e) => e.pointerType !== "mouse" && onActivate(r, c, "pointer")}
          onClick={() => onClickCell(r, c)}
          className={cn("group/cell p-px outline-none", clickable && cell.reached && "cursor-pointer")}
        >
          <div
            data-delay={cell.delay}
            className={cn(
              // Not positioned (and the hidden reading isn't either): hundreds of cells must not
              // each become a paint layer, or scrolling and hit-testing slow down.
              "grid h-9 min-w-13 place-items-center rounded-[4px] px-1.5 font-medium tabular-nums any-pointer-coarse:h-11",
              "forced-color-adjust-none forced-colors:border forced-colors:border-[CanvasText]",
              // Ring for the cell being read (pointer) and a focus ring for the keyboard.
              activeC === c && "ring-2 ring-sheen-fg ring-inset forced-colors:ring-[Highlight]",
              "group-focus-visible/cell:outline-solid group-focus-visible/cell:outline-2 group-focus-visible/cell:outline-offset-1 group-focus-visible/cell:outline-sheen-focus",
              !cell.fill && "bg-transparent",
              cell.fill && (cell.light ? "text-sheen-ink-on-dark" : "text-sheen-ink-on-light"),
            )}
            style={cell.fill ? { backgroundColor: cell.fill } : undefined}
          >
            <span aria-hidden={cell.reached ? true : undefined} className="[grid-area:1/1]">
              {cell.text}
            </span>
            {/* Visually hidden, in the same grid cell as the number (no absolute positioning). */}
            <span className="[grid-area:1/1] size-px overflow-hidden whitespace-nowrap [clip-path:inset(50%)]">
              {cell.sr}
            </span>
          </div>
        </td>
      ))}
    </tr>
  );
});

import { type ReactNode } from "react";

import { ChartValueTable, defaultCompact, MissingValue } from "../heatmap";
import { defaultCohortChartLabels, type CohortChartProps, cohortPercent, cohortModel } from "./parts";

/* ======================================================================
 * Table view
 * ====================================================================== */

/**
 * Props of CohortTable, the table view of the chart: the chart's data and formatting props plus a
 * hidden `caption` for screen readers.
 */
export type CohortTableProps = Pick<
  CohortChartProps,
  "data" | "valuesAre" | "periods" | "average" | "format" | "formatPercent" | "locale" | "labels"
> & {
  /** Sets a visually hidden caption that names the table. */
  caption?: string;
  /** Shown when there are no rows. */
  emptyState?: ReactNode;
};

/**
 * Every cohort as plain text: size, then "41.2% (529)" per period.
 *
 * @example
 * ```tsx
 * import { CohortTable } from "@sheenui/theme";
 *
 * const cohorts = [
 *   { cohort: "Jan 2026", size: 1200, values: [1200, 540, 410, 360] },
 *   { cohort: "Feb 2026", size: 1350, values: [1350, 600, 455, null] },
 * ];
 *
 * export function Example() {
 *   return (
 *     <CohortTable data={cohorts} caption="Retention table" />
 *   );
 * }
 * ```
 *
 * @see /charts/cohort-retention
 */
export function CohortTable({
  data,
  valuesAre,
  periods,
  average = true,
  format: formatProp,
  formatPercent: formatPercentProp,
  locale,
  labels: labelOverrides,
  caption,
  emptyState,
}: CohortTableProps) {
  const labels = { ...defaultCohortChartLabels, ...labelOverrides };
  const format = formatProp ?? defaultCompact(locale);
  const pct = formatPercentProp ?? cohortPercent(locale);
  const { rows, periods: n } = cohortModel(data, valuesAre, periods, average);
  return (
    <ChartValueTable
      caption={caption}
      emptyState={emptyState}
      columns={[
        { label: labels.cohort },
        { label: labels.count },
        ...Array.from({ length: n }, (_, p) => ({ label: labels.period(p) })),
      ]}
      rows={rows.map((row) => [
        row.average ? `${labels.average} (${labels.averageNote.toLocaleLowerCase()})` : row.name,
        format(row.size),
        ...row.cells.map((c) =>
          c.ratio === null ? <MissingValue label={labels.notYet} /> : `${pct(c.ratio)} (${format(c.count ?? 0)})`,
        ),
      ])}
    />
  );
}

